import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"山地剝","description":"周易折中 - 山地剝","frontmatter":{"title":"山地剝","description":"周易折中 - 山地剝"},"headers":[],"relativePath":"classics/zhezhong/029.md","filePath":"classics/zhezhong/029.md"}'),h={name:"classics/zhezhong/029.md"};function n(p,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="山地剝" tabindex="-1">山地剝 <a class="header-anchor" href="#山地剝" aria-label="Permalink to “山地剝”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>剝卦序：賁者，飾也；致飾然後亨，則盡矣，故受之以剝。夫物至於文飾，亨之極也，極則必反，故賁終則剝也。卦五陰而一陽，陰始自下生，漸長至於盛極，群陰湏剝於陽，故為剝也。以二體言之，山附於地，山高起地上而反附者於地，頹剝之象也。</p><p>剝：不利有攸往</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>剝落也。五陰在下而方生一陽在上而將盡，陰盛長而陽消落，九月之卦也。陰盛陽衰，小人壯而君子病。又內坤外艮，有順時而止之象。故佔得之者，不可以有所往也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>剝者，群陰長盛，消剝於陽之時。眾小人剝喪於君子，故君子不利有所往。唯當巽言晦跡，隨時消息，以免小人之害也。</p><p>象曰：山附於地，剝；上以厚下安宅</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>艮重於坤，山附於地也。山高起於地而反附著於地，圯剝之象也。上謂人君與居人上者，觀剝之象而厚固其下以安其居也。下者上之本，未有基本固而能剝者也，故上之剝必自下。下剝則上危矣，為人上者知理之如是，則安養人民以厚其本，乃所以安其居也。書曰：“民惟邦本，本固邦寧。”</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>虞氏翻曰 ：山高絕於地，今附地者，明被剝矣。君當厚錫於下，然後得安其居。</p></li><li><p>劉氏牧曰 ：山以地為基，厚其地則山保其高；君以民為本，厚其下則君安於上。</p></li><li><p>司馬氏光曰 ：基薄則牆頹，下薄則上危。故君子厚其下者，所以自安其居也。</p></li><li><p>朱子語類雲 ：惟其地厚，所以山安其居而不搖。人君厚下以得民，則其位亦安而不搖，猶所謂“本固邦寧”也。</p></li></ul><p>彖曰：剝，剝也。柔變剛也</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>以卦體釋卦名義，言柔進幹陽，變剛為柔也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li>陳氏友文曰：《夬彖》曰“剛決柔”，而《剝》曰“柔變剛”，何也？君子之去小人，聲其罪與天下共棄之，名正言順，故曰“決”；小人之慾去君子，辭不順理不直，必萋斐浸潤以侵蝕之，故曰“變”。一字之閒，君子小人之情狀皦然矣。</li></ul><p>不利有攸往，小人長也。順而止之，觀象也。君子尚消息盈虛，天行也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦體卦徳釋卦辭。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>剝，剝也，謂剝落也。柔變剛也，柔長而剛變也。夏至一陰生而漸長，一陰長則一陽消，至於建戌則極而成剝，是陰柔變剛陽也。陰小人之道方長盛而剝消於陽，故君子不利有所往也。君子當剝之時，知不可有所往，順時而止，乃能觀剝之象也。卦有順止之象，乃處剝之道，君子當觀而體之。君子尚消息盈虛，天行也。君子存心消息盈虛之理而能順之，乃合乎天行也。理有消衰有息長，有盈滿有虛損，順之則吉，逆之則兇。君子隨時敦尚，所以事天也。</p><p>初六：剝床以足，蔑貞兇</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>剝自下起，滅正則兇，故其佔如此。蔑，滅也。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>陰之剝陽，自下而上。以床為象者，取身之所處也。自下而剝，漸至於身也。剝床以足，剝床之足也。剝始自下，故為剝足。陰自下進，漸消滅於貞正，兇之道也。蔑，無也，謂消亡於正道也。陰剝陽，柔變剛，是邪侵正，小人消君子，其兇可知。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li>俞氏琰曰 ：陰之消陽自下而進，初在下，故為剝床而先以床足滅於下之象。當此“不利有攸往”之時，唯宜順時而止耳。貞兇，戒佔者固執而不知變，則兇也。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>俞氏之說是以“蔑”字屬上句讀，蓋自象傳㓕下㸔出，亦可備一說。</p><p>象曰：剝床以足，以滅下也</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>取床足為象者，以陰侵沒陽於下也。滅，沒也，侵滅正道自下而上也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li>虞氏翻曰 ：床所以安人，在下故稱足。先從下剝，漸及於上，故曰“以滅下也”。</li></ul><p>六二：剝床以辨，蔑貞兇</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>辨，床幹也，進而上矣。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>辨，分隔上下者，床之幹也。陰漸進而上，剝至於辨，愈滅於正也，兇益甚矣。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li>俞氏琰曰 ：既滅初之足於下，又滅二之辨於中，則進而上矣。得此佔者，若猶固執而不知變，則其兇必也。</li></ul><p>象曰：剝床以辨，未有與也</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>言未大盛。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>陰之侵剝於陽，得以益盛，至於剝辨者，以陽未有應與故也。小人侵剝君子，若君子有與，則可以勝小人，不能為害矣。唯其無與，所以被蔑而兇。當消剝之時而無徒與，豈能自存也？言未有與，剝之未盛，有與猶可勝也。示人之意深矣。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>崔氏憬曰 ：辨當在笫足之間，是床梐也。未有與者，言至三則應，故二未有與也。</p></li><li><p>吳氏澄曰 ：若六三之剝，之唯其有與也。</p></li><li><p>龔氏煥曰 ：六二陰柔中正，使上有陽剛之與，則必應之助之而不為剝矣。惟其無與，所以雜於群陰之中而為剝。若三則有與，故雖不如二之中正，而得無咎。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>崔氏、吳氏、龔氏之說皆得文意。六三不中正而辭優於二，故聖人以“未有與”失上下明之。</p><p>六三：剝之無咎</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>眾陰方剝陽，而已獨應之，去其黨而從正，無咎之道也。佔者如是，則得無咎。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>眾陰剝陽之時，而三獨居剛，應剛與上下之陰異矣。志從於正，在剝之時為無咎者也。三之為可謂善矣，不言吉何也？曰：方群陰剝陽，眾小人害君子，三雖從正，其𫝑孤弱，所應在無位之地，於斯時也難乎免矣，安得吉也？其義為無咎耳。言其無咎，所以勸也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>荀氏爽曰：眾皆剝陽，三獨應上，無剝害意，是以無咎。</p></li><li><p>王氏弼曰：與上為應，群陰剝陽，我獨協焉。雖處於剝，可以無咎。</p></li><li><p>胡氏炳文曰：剝之三即復之四。復六四不許以吉，剝六三許以無咎，何也？曰：復君子之事，明道不計功，不以吉許之可也。剝小人之事，小人中獨知有君子，不以無咎許之，無以開其補過之門也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>王氏、程子皆以“剝之無咎”連讀，言此乃剝時之無咎者也。玩本義似以“剝之”為“剝去其黨”。</p><p>象曰：剝之無咎，失上下也</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>上下謂四陰。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>三居剝而無咎者，其所處與上下諸陰不同，是與其同類相失，於處剝之道為無咎，如東漢之呂強是也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰 ：三上下各有二陰，而三獨應於陽，則失上下也。</p></li><li><p>丘氏富國曰 ：上謂四五，下謂初二，違去四陰而獨從剛，故曰失上下也。</p></li></ul><p>六四：剝床以膚，兇</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>陰禍切身，故不復言蔑貞，而直言兇也。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>始剝於床足，漸至於膚。膚，身之外也，將滅其身矣，其兇可知。陰長已盛，陽剝已甚，貞道以消，故更不言蔑貞，直言兇也。</p><p>象曰：剝床以膚，切近災也</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>五為君位，剝已及四，在人則剝其膚矣。剝及其膚，身垂於亡矣，切近於災禍也。</p><p>六五：貫魚以宮人寵，無不利</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>魚陰物，宮人陰之美而受制於陽者也。五為眾陰之長，當率其類受制於陽，故有此象。而佔者如是，則無不利也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>剝及君位，剝之極也，其兇可知。故更不言剝，而別設義以開小人遷善之門。五，群陰之主也，魚陰物，故以為象。五能使群陰順序如貫魚然，反獲寵愛於在上之陽，如宮人，則無所不利也。宮人，宮中之人，妻妾侍使也。以陰言且取獲寵愛之義，以一陽在上，眾陰有順從之道，故發此義。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張子曰：陰陽之際近必相比，六五能上附於陽，反制群陰，不使進逼，方得處剝之善。下無剝之之憂，上得陽功之庇，故曰無不利。</p></li><li><p>熊氏良輔曰：卦本為陰剝陽而陽兇，爻則以剝陽而見兇。故五則以順上為無不利，三則以應上為無咎，而上則有碩果得輿之象焉。</p></li><li><p>張氏振淵曰：遁陰長而猶微，可制也，則告陽以制陰之道曰畜臣妾。剝陰長已極，不可制矣，則教陰以從陽之道曰以宮人寵。</p></li></ul><p>象曰：以宮人寵，終無尤也</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>群陰消剝於陽以至於極，六五若能長率群陰，駢首順序，反獲寵愛於陽，則終無過尤也。於剝之將終，復發此義，聖人勸遷善之意深切之至也。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>五以陰居尊，取后妃之象，而為貫魚。以宮人寵，則豈有妒害瀆亂以剝其君之尤哉？</p><p>上九：碩果不食，君子得輿，小人剝廬</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>一陽在上，剝未盡而能復生。君子在上，則為眾陰所載；小人居之，則剝極於上，自失所覆，而無復“碩果得輿”之象矣。取象既明，而君子、小人其佔不同，聖人之情益可見矣。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>諸陽削剝已盡，獨有上九一爻尚存，如碩大之果，不見食，將見覆生之理。上九亦變，則純陰矣。然陽無可盡之理，變於上則生於下，無間可容息也。聖人發明此理，以見陽與君子之道不可亡也。或曰：“剝盡則為純坤，豈復有陽乎？”曰：“以卦配月，則坤當十月。以氣消息言，則陽剝為坤，陽來為復，陽未嘗盡也。剝盡於上，則復生於下矣。故十月謂之陽月，恐疑其無陽也。陰亦然，聖人不言耳。陰道盛極之時，其亂可知。亂極則自當思治，故眾心願載於君子，君子得輿也。《詩》‘匪風下泉’，所以居變風之終也。理既如此，在卦亦眾陰宗陽，為共載之象。小人剝廬，若小人則當剝之極，剝其廬矣，無所容其身也。”更不論爻之陰陽，但言小人處剝極，則及其廬矣。廬取在上之象。或曰：“陰陽之消，必待盡而後復生於下，此在上便有復生之義，何也？”《夬》之上六何以言“終有兇”？曰：“上九居剝之極，止有一陽，陽無可盡之理，故明其有復生之義，見君子之道不可亡也。《夬》者，陽消陰，陰小人之道也，故但言其消亡耳，何用更言卻有復生之理乎？”</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>程子曰 ：“息訓為生者，蓋息則生矣。中無間斷，碩果不食，則便為復也。”</p></li><li><p>楊氏文煥曰 ：“貫魚者，眾陰在下之象也；碩果者，一陽在上之象也。”</p></li><li><p>胡氏炳文曰 ：“乾為木果，眾陽皆變而上獨存，有碩果不食象。果中有仁，天地生生之心存焉。碩果專以象言，得輿、剝廬兼佔而言。床上之藉，下以安者也；廬下之藉，上以安者也。始而剝床，欲上失所安；今而剝廬，自失所安矣。自古小人慾害君子，亦豈小人之利哉？”</p></li><li><p>蔡氏清曰 ：“《易》固為君子謀，然其為君子謀者，亦所以為小人謀也。觀小人剝廬之辭可見。蓋道理自是如此，天地間豈可一日無善類哉？不然，人之類滅矣。可見聖人非姑為是抑彼以伸此也。”</p></li><li><p>喬氏中和曰 ：“碩果不食，核也，仁也，生生之根也。自古無不朽之株，有相傳之果，此剝之所以復也。”</p></li></ul><p>象曰：君子得輿，民所載也；小人剝廬，終不可用也</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>正道消剝既極，則人復思治，故陽剛君子為民所承載也。若小人處剝之極，則小人之窮耳，終不可用也。非謂九為小人，但言剝極之時，小人如是也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>朱子語類雲 ：唯君子乃能覆蓋小人，小人必賴君子以保其身。今小人慾剝君子，則君子亡而小人亦無所容其身，如自剝其廬也。且自古小人慾害君子，到害得盡後，國破家亡，其小人曾有存活得者否？故聖人於象曰“君子得輿，民所載也；小人剝廬，終不可用也”。</li></ul>',101)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
